def maxChunks(nums):
    n = len(nums)
    suf = [0] * (n + 1)
    suf[n] = float("inf")
    for i in range(n - 1, -1, -1):
        suf[i] = min(suf[i + 1], nums[i])
    chunks = 1
    pref = nums[0]
    for i in range(n - 1):
        pref = max(pref, nums[i])
        if pref <= suf[i + 1]:
            chunks += 1
    return chunks
